package actions

const (acceptancePredicateKey = "acceptance_predicate"; acceptancePredicateRejectedKey = "acceptance_predicate_rejected")
const cardinalNeedle = "$cardinal"

var acceptancePredicateFields = map[string]map[string]bool{   // closed key set PER TYPE
    "text_absent":  {"field": true, "page": true, "values": true},
    "text_present": {"field": true, "page": true, "values": true, "min": true},
    "text_order":   {"field": true, "page": true, "before": true, "after": true},
}
var acceptancePredicateTextFields = map[string]bool{"meta_description": true, "title": true}

type AcceptancePredicateVerdict string
const (PredicateRefutes AcceptancePredicateVerdict = "refutes"; PredicateHolds = "holds"; PredicateInapplicable = "inapplicable")

// word-boundary matcher: unanchored, "we" is inside "web"
func needleRe(needle string) (*regexp.Regexp, error) {
    pat := regexp.QuoteMeta(needle)
    if isWordEdge(rune(needle[0]))             { pat = `\b` + pat }
    if isWordEdge(rune(needle[len(needle)-1])) { pat = pat + `\b` }
    return regexp.Compile(`(?i)` + pat)
}

// returns the MATCHED TEXT, not the needle: a verdict saying $cardinal appears at 0 is not evidence
func needleMatch(text, needle string) (int, string, error) {
    if needle == cardinalNeedle { pos, matched := firstCardinalMatch(text); return pos, matched, nil }
    loc := re.FindStringIndex(text); if loc == nil { return -1, "", nil }
    return loc[0], text[loc[0]:loc[1]], nil
}

// reuses digitCardinalSpans + cardinalPointWordRe from verify_cited_cardinals_action.go
func firstCardinalMatch(text string) (int, string) {
    best, matched := -1, ""
    for _, span := range digitCardinalSpans(text) { if best == -1 || span[0] < best { best, matched = span[0], text[span[0]:span[1]] } }
    if loc := cardinalPointWordRe.FindStringIndex(text); loc != nil && (best == -1 || loc[0] < best) { best, matched = loc[0], text[loc[0]:loc[1]] }
    return best, matched
}

func EvaluateAcceptancePredicate(pred map[string]interface{}, subject AcceptancePredicateSubject) (AcceptancePredicateVerdict, string) {
    typ := strings.ToLower(strings.TrimSpace(pred["type"].(string)))
    allowed, known := acceptancePredicateFields[typ]
    if !known { return PredicateInapplicable, "unknown predicate type ..." }
    for k := range pred { if k != "type" && !allowed[k] { return PredicateInapplicable, "key %q is not read by %s, so the predicate asserts less than it appears to" } }
    if !acceptancePredicateTextFields[field] { return PredicateInapplicable, "... this platform reads meta_description and title" }
    text := subject.MetaDescription; if field == "title" { text = subject.Title }
    switch typ {
    case "text_absent":  // refutes if ANY value is present
        for _, v := range values { if pos, matched, _ := needleMatch(text, v); pos >= 0 { return PredicateRefutes, fmt.Sprintf("%s of %q contains %q at %d", field, subject.Page, matched, pos) } }
        return PredicateHolds, "... contains none of ..."
    case "text_present": // refutes if fewer than min are present; min > len(values) is unsatisfiable -> inapplicable
        if minCount > len(values) { return PredicateInapplicable, "min %d exceeds the %d values listed, so the predicate can never hold" }
        if len(found) < minCount  { return PredicateRefutes, "... fewer than the %d demanded" }
        return PredicateHolds, "... already contains ..."
    case "text_order":   // refutes if NO before-needle is present, or an after-needle precedes every before-needle
        if posBefore == -1 { return PredicateRefutes, "states none of ..., so nothing can precede ..." }
        if posAfter  == -1 { return PredicateHolds,   "... contains none of ... at all" }
        if posAfter < posBefore { return PredicateRefutes, fmt.Sprintf("in %s of %q, %q appears at %d, before %q at %d", field, subject.Page, firstAfter, posAfter, firstBefore, posBefore) }
        return PredicateHolds, "... precedes ..."
    }
}

func VerifyAcceptancePredicatesAction(ctx context.Context, params ActionParams) (interface{}, error) {
    inputs, err := datahelpers.ExtractActionInputs(params.CollectedData, config, VerifyAcceptancePredicatesInputSpec, logger)
    if err != nil { return nil, fmt.Errorf("input extraction failed: %w", err) }   // misconfiguration fails LOUD
    siteID, err := uuid.Parse(inputs.Get("site_id")); if err != nil { return nil, fmt.Errorf("invalid site_id: %w", err) }

    items, resolved := resolveFindingsList(datahelpers.ExtractNestedField(params.CollectedData, findingsField))
    if !resolved {
        // NO "findings" KEY. An empty array is write_audit_findings recognised silence and ARMS retraction.
        return map[string]interface{}{"checked": 0, "kept": 0, "rejected": 0, "findings_resolved": false, "reason": "no findings list at " + findingsField}, nil
    }
    subjects, err := loadAcceptancePredicateSubjects(ctx, params, siteID)   // WHERE clause copied from the offer surface own query
    if err != nil { subjects = nil }   // every predicate becomes inapplicable; the findings still get filed

    for i, raw := range items {
        item, ok := raw.(map[string]interface{}); if !ok { out = append(out, raw); continue }
        if _, present := item[acceptancePredicateKey]; !present { out = append(out, raw); continue }  // silence is free
        copied := shallowCopy(item); delete(copied, acceptancePredicateKey); delete(copied, acceptancePredicateRejectedKey)
        subject, found := subjects[predicatePageName(pred, item)]
        if !found { copied[acceptancePredicateRejectedKey] = AcceptancePredicateRejection{Verdict: "inapplicable", Reason: "page %q is not on this site active surface", Predicate: pred}; rejected++; out = append(out, copied); continue }
        verdict, reason := EvaluateAcceptancePredicate(pred, subject)
        if verdict == PredicateRefutes {
            stored := shallowCopy(pred)
            stored["verdict_at_emission"] = string(PredicateRefutes)
            stored["evidence_at_emission"] = reason
            copied[acceptancePredicateKey] = stored; kept++
        } else {
            copied[acceptancePredicateRejectedKey] = AcceptancePredicateRejection{Verdict: string(verdict), Reason: reason, Predicate: pred}; rejected++
        }
        out = append(out, copied)   // EVERY finding survives, always
    }
    return map[string]interface{}{"findings": out, "checked": len(items), "kept": kept, "rejected": rejected, "rejections": rejections, "findings_resolved": true}, nil
}

func loadAcceptancePredicateSubjects(ctx context.Context, params ActionParams, siteID uuid.UUID) (map[string]AcceptancePredicateSubject, error) {
    rows, err := params.DB.QueryContext(ctx, `
        SELECT name, COALESCE(title, ''), COALESCE(meta_description, '')
        FROM pages WHERE site_id = $1 AND status = 'active'
          AND NOT (deployed_at IS NULL AND COALESCE(build_status, '') = 'planned')`, siteID)
}

var VerifyAcceptancePredicatesInputSpec = datahelpers.ActionInputSpec{
    CheckConfig: true, Required: []string{"site_id"}, Optional: []string{"findings_field"},
}   // NO other knobs: every optional key is accumulated authority (RFC_022 budget)
func init() { datahelpers.RegisterActionInputSpec("verify_acceptance_predicates", VerifyAcceptancePredicatesInputSpec) }

const wdIndexMeta = "Sixty-three browser tools for web design and development. No account, no upload, everything runs in your browser."
const wdAboutMeta = "Curated guides and tools for modern web development, from HTML semantics to responsive design."
const wdLearnIndexMeta = "Learn the reasoning behind web design: why breakpoints fail, how to use math for layouts, and when to break the rules."
const wdIndexFixed = "No account, no upload, everything runs in your browser. Sixty-three browser tools for web design and development."

func TestTheWorkedFailureIsRefutedByItsOwnField(t *testing.T) {
    verdict, reason := EvaluateAcceptancePredicate(
        orderPred("index", []interface{}{"no account", "no upload", "nothing stored"}, []interface{}{cardinalNeedle}),
        predSubject("index", "", wdIndexMeta))
    if verdict != PredicateRefutes { t.Fatalf("verdict = %s (%s); the live meta opens with a word cardinal", verdict, reason) }
    if !strings.Contains(reason, "Sixty-three") || !strings.Contains(reason, "No account") { t.Errorf("reason does not quote both sides in the page own case: %s", reason) }
    if !strings.Contains(reason, " at 0,") { t.Errorf("reason does not carry the offsets: %s", reason) }
}

func TestTheFixTurnsTheSamePredicateOff(t *testing.T) {   // same predicate, mutated string -> holds
    verdict, _ := EvaluateAcceptancePredicate(samePred, predSubject("index", "", wdIndexFixed))
    if verdict != PredicateHolds { t.Fatalf("a gate that cannot be turned off by the repair it demands is a permanent alarm") }
}

func TestOnlyTheWordScannerCatchesTheWordForm(t *testing.T) {   // discrimination: the digits-only precedent misses it
    if got := len(digitCardinalSpans(wdIndexMeta)); got != 0 { t.Fatalf("digit spans = %d, want 0 - the defect is spelled out", got) }
    if pos, matched := firstCardinalMatch(wdIndexMeta); pos != 0 || !strings.EqualFold(matched, "Sixty-three") { t.Fatalf("firstCardinalMatch = (%d, %q)", pos, matched) }
}

func TestWordBoundariesPreventTheFalseRefutation(t *testing.T) {
    pred := textAbsent("learn-index", []interface{}{"we", "our"})
    if v, r := EvaluateAcceptancePredicate(pred, predSubject("learn-index", "", wdLearnIndexMeta)); v != PredicateHolds { t.Fatalf("web is not we: %s %s", v, r) }
    if v, _ := EvaluateAcceptancePredicate(pred, predSubject("learn-index", "", "Learn why we built our layout tools the way we did.")); v != PredicateRefutes { t.Fatalf("control failed: standalone we must refute") }
    if !strings.Contains(strings.ToLower(wdLearnIndexMeta), "we") { t.Fatal("the corpus string no longer contains the substring we; this test premise has moved") }
}

func TestAPredicateThatAlreadyHoldsIsRejected(t *testing.T) {   // the vacuous case
    res := runPredicateGate(t, []interface{}{finding("about", textAbsent("", []interface{}{"shibboleth"}))})
