func TestAnUnresolvableFindingsPathOmitsTheKey(t *testing.T) {   // the retraction trap
    out, err := VerifyAcceptancePredicatesAction(ctx, paramsWithFindingsField("analysis.result.nowhere"))
    if err != nil { t.Fatalf("an unresolvable path must not fail the run: %v", err) }
    if _, present := out.(map[string]interface{})["findings"]; present { t.Error("the findings key must be ABSENT, so write_audit_findings takes its own nil branch and retracts nothing") }
}
