BEGIN;
SELECT snapshot_agent('offer-analyser', '601_acceptance_predicates: pre-update');

DO $$ BEGIN   -- already-applied gate
    IF (SELECT count(*) FROM agent_definitions WHERE type='offer-analyser' AND is_active
          AND default_config->'workflow'->'steps' ? 'verify_finding_predicates') > 0 THEN
        RAISE EXCEPTION '601: already applied'; END IF; END $$;

CREATE TEMP TABLE _601_target ON COMMIT DROP AS
SELECT id FROM agent_definitions
 WHERE is_active AND NOT COALESCE(is_snapshot,false) AND deleted_at IS NULL AND type = 'offer-analyser'
   AND default_config->'workflow'->'steps'->'set_audit_source'->>'next_step' = 'verify_ordering_cardinals'
   AND default_config->'workflow'->'steps'->'verify_ordering_cardinals'->>'next_step' = 'write_offer_ordering'
   AND default_config->'workflow'->'steps'->'write_offer_ordering'->>'next_step' = 'write_offer_findings'
   AND default_config->'workflow'->'steps'->'write_offer_findings'->'config'->>'findings_field' = 'offer_analysis.result.findings';

DO $$ BEGIN   -- exactly one target, and exactly one ACTIVE row, stated separately so the failure names its cause
    IF (SELECT count(*) FROM _601_target) <> 1 THEN RAISE EXCEPTION '601 needle-gate: expected exactly 1, found %', n; END IF;
    IF total_active <> 1 THEN RAISE EXCEPTION '601 needle-gate: offer-analyser has % active definition rows', total_active; END IF; END $$;

DO $$ BEGIN   -- PROMPT ANCHOR GATE: replace() on a missed anchor is a SILENT no-op that still reports UPDATE 1
    anchor := 'Bad: the homepage should be more benefit-led sentence, verbatim';
    occurrences := (length(prompt) - length(replace(prompt, anchor, ''))) / length(anchor);
    IF occurrences <> 1 THEN RAISE EXCEPTION '601 prompt-anchor gate: occurs % time(s), expected exactly 1', occurrences; END IF; END $$;

UPDATE agent_definitions
   SET default_config = jsonb_set(jsonb_set(jsonb_set(default_config,
         '{workflow,steps,verify_finding_predicates}',
         jsonb_build_object('action','verify_acceptance_predicates',
             'config', jsonb_build_object('site_id','site_record.site_id','findings_field','offer_analysis.result.findings'),
             'next_step','write_offer_findings', 'output_field','predicates_checked', 'description','features_open/030 v2(d) ...'), true),
         '{workflow,steps,write_offer_ordering,next_step}', '"verify_finding_predicates"'::jsonb, false),
         '{workflow,steps,write_offer_findings,config,findings_field}', '"predicates_checked.findings"'::jsonb, false),
       updated_at = now()
 WHERE id IN (SELECT id FROM _601_target);

UPDATE agent_definitions   -- the prompt contract, spliced after the anchor, NOT into the OUTPUT skeleton
   SET default_config = jsonb_set(default_config, '{workflow,steps,run_offer_analysis,config,prompt}',
         to_jsonb(replace(prompt, anchor, $rule$<anchor>

ACCEPTANCE PREDICATE - optional, per finding, and usually omitted. If a NECESSARY condition of your acceptance_test can be stated
mechanically over ONE page meta description or title, add "acceptance_predicate" to that finding. If it cannot, OMIT THE KEY ENTIRELY.
Three rules. (1) A predicate can only ever REFUTE ... (2) It must be FALSE OF THE PAGE AS IT IS TODAY ... (3) Only these three shapes ...
{"type": "text_absent", "page": "about", "field": "meta_description", "values": ["curated", "hand-picked"]}
{"type": "text_present", "page": "index", "field": "title", "values": ["Kubernetes", "Kafka", "Postgres"], "min": 2}
{"type": "text_order", "page": "index", "field": "meta_description", "before": ["no account"], "after": ["$cardinal"]}$rule$)), false)
 WHERE id IN (SELECT id FROM _601_target);

DO $$ BEGIN   -- VERIFY as DO/RAISE: ON_ERROR_STOP does not fire on a non-empty SELECT
    IF step->>'action' <> 'verify_acceptance_predicates' THEN RAISE EXCEPTION '601 verify: gate step missing or wrong action'; END IF;
    IF cfg->'workflow'->'steps'->'write_offer_ordering'->>'next_step' <> 'verify_finding_predicates' THEN RAISE EXCEPTION '601 verify: write_offer_ordering still bypasses the gate'; END IF;
    IF cfg->'workflow'->'steps'->'write_offer_findings'->'config'->>'findings_field' <> 'predicates_checked.findings' THEN RAISE EXCEPTION '601 verify: the findings write still reads the UNCHECKED model output'; END IF;
    IF n_steps <> 10 THEN RAISE EXCEPTION '601 verify: expected 10 workflow steps, found %', n_steps; END IF;
    IF prompt NOT LIKE '%can only ever REFUTE%' THEN RAISE EXCEPTION '601 verify: the refute-only rule is missing from the prompt'; END IF;
    mentions := (length(prompt) - length(replace(prompt,'acceptance_predicate',''))) / length('acceptance_predicate');
    IF mentions <> 1 THEN RAISE EXCEPTION '601 verify: occurs % times, expected exactly 1 - it must NOT be in the OUTPUT skeleton', mentions; END IF;
END $$;
COMMIT;
